def plan(series, frm, to, step):
    res = RAW if to - frm <= 2*DAY else (M1 if to - frm <= 60*DAY else H1)
    buckets = range(floor(frm / res.bucket), floor((to - 1) / res.bucket) + 1)
    blocks = block_index.lookup(series, res, buckets)
    blocks = [b for b in blocks if b.max_ts >= frm and b.min_ts < to]
    return Plan(res, sorted(blocks, key=lambda b: b.min_ts))

def encode(points):
    out.write(points[0].ts, 64); out.write_float(points[0].v)
    prev_ts, prev_delta, prev_v = points[0].ts, 0, points[0].v
    for p in points[1:]:
        delta = p.ts - prev_ts; dod = delta - prev_delta
        if dod == 0: out.bit(0)
        elif -63 <= dod <= 64: out.bits('10'); out.write(dod, 7)
        else: out.bits('11'); out.write(dod, 32)
        x = float_bits(p.v) ^ float_bits(prev_v)
        if x == 0: out.bit(0)
        else: out.bit(1); write_leading_trailing_and_meaningful(x)
        prev_ts, prev_delta, prev_v = p.ts, delta, p.v

def merge(streams, limit, after=None):
    heap = [(s.peek().ts, s.peek().seq, i) for i, s in enumerate(streams) if s.peek()]
    heapify(heap); out = []; last = None
    while heap and len(out) < limit:
        ts, seq, i = heappop(heap); p = streams[i].next()
        if after and (ts, seq) <= after: pass
        elif last and ts == last.ts: out[-1] = max(out[-1], p, key=lambda q: q.seq)
        else: out.append(p); last = p
        if streams[i].peek(): heappush(heap, (streams[i].peek().ts, streams[i].peek().seq, i))
    return out, (out[-1].ts, out[-1].seq) if out else None
